import{d as g,C as e,o as h,c as d,j as i,a,E as t,a3 as m}from"./chunks/framework.Q4yG9rk_.js";const b=JSON.parse('{"title":"中庸·第23章","description":"《中庸》第 23 章——其次致曲：从善端的一偏推致开去，诚则形、形则著、著则明、明则动、动则变、变则化。","frontmatter":{"title":"中庸·第23章","description":"《中庸》第 23 章——其次致曲：从善端的一偏推致开去，诚则形、形则著、著则明、明则动、动则变、变则化。","category":"guide","aliases":["第23章","中庸第23章","其次致曲"],"source":["《礼记》","《四书章句集注》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/zhongyong/chapter-23.md","filePath":"lizhimingde/sishu-wujing/zhongyong/chapter-23.md","lastUpdated":1790316338000}'),u={name:"lizhimingde/sishu-wujing/zhongyong/chapter-23.md"},x=g({...u,setup(p){const r=[{id:"zhiqv",label:"其次致曲 · 曲能有诚",showLabel:!0,sentences:[["其次",{text:"致曲",glossary:"zhiqu"},"，曲能有诚，"]],note:"「其次致曲」——次于至诚的人（其次），就着自己善端发见的一偏之处（曲），推致开去；「曲能有诚」：把这善端推致到极处，同样能有诚。此章为不能「生知安行」的人另开一路切实功夫。"},{id:"lianSuo",label:"诚则形 · 形著明动变化 · 唯天下至诚为能化",showLabel:!0,sentences:[["诚则",{text:"形",glossary:"xing"},"，形则",{text:"著",glossary:"zhu"},"，著则",{text:"明",glossary:"ming"},"，明则",{text:"动",glossary:"dong"},"，动则",{text:"变",glossary:"bian"},"，变则",{text:"化",glossary:"hua"},"，唯天下至诚为能化。"]],note:"「诚则形，形则著，著则明，明则动，动则变，变则化」——诚积于中便显露于外（形＝积中而发外），显露则更加显著（著），显著则光辉发越（明），光辉则感动他物（动），感动则使物转变（变），转变则至于化育（化＝不知其所以然之至境）。故结以「唯天下至诚为能化」。此节与本节「致曲」相承：致曲者积而至化，其妙亦不异于圣人。"}],o=[{id:"qici",term:"其次",pinyin:"qí cì",meaning:"朱注：「其次，通大贤以下凡诚有未至者而言也。」即未达至诚的人。"},{id:"zhiqu",term:"致曲",pinyin:"zhì qū",meaning:"致：推致；曲：一偏。朱注：「其次则必自其善端发见之偏，而悉推致之，以各造其极也。」——从自己善端的那一偏开始，推而极之。"},{id:"xing",term:"形",pinyin:"xíng",meaning:"朱注：「形者，积中而发外。」内在积满，自然显露于外。"},{id:"zhu",term:"著",pinyin:"zhù",meaning:"更加显著。朱注：「著，则又加显矣。」"},{id:"ming",term:"明",pinyin:"míng",meaning:"朱注：「明，则又有光辉发越之盛也。」"},{id:"dong",term:"动",pinyin:"dòng",meaning:"朱注：「动者，诚能动物。」"},{id:"bian",term:"变",pinyin:"biàn",meaning:"朱注：「变者，物从而变。」"},{id:"hua",term:"化",pinyin:"huà",meaning:"朱注：「化，则有不知其所以然者。」化是至境，故曰「唯天下至诚为能化」。"}];return(c,n)=>{const s=e("DaoTextReading"),l=e("DaoKeywordCards");return h(),d("div",null,[n[0]||(n[0]=i("h1",{id:"中庸·第23章",tabindex:"-1"},[a("中庸·第23章 "),i("a",{class:"header-anchor",href:"#中庸·第23章","aria-label":'Permalink to "中庸·第23章"'},"​")],-1)),n[1]||(n[1]=i("h2",{id:"【原典层】原文",tabindex:"-1"},[a("【原典层】原文 "),i("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),n[2]||(n[2]=i("p",null,[a("第二十三章是给「其次」的人——未达至诚者——的一条路："),i("strong",null,"致曲"),a("。从自己善端的一偏推致开去，然后是一串连锁：诚 → 形 → 著 → 明 → 动 → 变 → 化。默认竹简沉浸通读；切「经典阅读」可点生词。")],-1)),t(s,{colophon:"其次致曲 · 形著明动变化",tone:"ink",sections:r,glossary:o,"default-mode":"slips","aria-label":"中庸·第23章 原文"}),n[3]||(n[3]=i("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[a("【原典层】注音与字词 "),i("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),t(l,{items:[{term:"其次",pinyin:["qí","cì"],meaning:"朱注：「通大贤以下凡诚有未至者而言也。」"},{term:"致曲",pinyin:["zhì","qū"],meaning:"致：推致；曲：一偏。从自己善端的那一偏下手，推而极之——这是给多数人的路。"},{term:"形",pinyin:["xíng"],meaning:"积中发外——内在积满，自然外露。"},{term:"著",pinyin:["zhù"],meaning:"更加显著。"},{term:"明",pinyin:["míng"],meaning:"光辉发越。三者是「诚」由内而外的次第。"},{term:"动",pinyin:["dòng"],meaning:"诚能动物。"},{term:"变",pinyin:["biàn"],meaning:"物从而变。"},{term:"化",pinyin:["huà"],meaning:"不知其所以然。化是至境。"}]}),n[4]||(n[4]=m('<p>全篇生词的完整释义在<a href="/Dao/reference/glossary/">字词释义字典</a>中统一维护。</p><h2 id="【原典层】白话译文" tabindex="-1">【原典层】白话译文 <a class="header-anchor" href="#【原典层】白话译文" aria-label="Permalink to &quot;【原典层】白话译文&quot;">​</a></h2><p><strong>其次致曲 · 曲能有诚</strong>：次一等的人，从自己善端的一偏推致开去；一偏能推致，就能有诚。</p><p><strong>诚则形 · 唯天下至诚为能化</strong>：诚，就会显露于外；显露就会显著；显著就会光明；光明就会感动他物；感动就会使它转变；转变就会化育——只有天下至诚的人，才能化育。</p><h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一篇在说什么" tabindex="-1">象：这一篇在说什么 <a class="header-anchor" href="#象-这一篇在说什么" aria-label="Permalink to &quot;象：这一篇在说什么&quot;">​</a></h3><p>第二十三章与上章正好相对：上章说「至诚尽性」（那是圣人），本章说「<strong>其次致曲</strong>」（那是我们）。</p><p>「致曲」的意思，朱注解得很清楚：<strong>「自其善端发见之偏，而悉推致之，以各造其极也」</strong>——从自己善念显露的那一处（哪怕只是一偏），推而致之，做到极处。</p><p>接着是一串连锁：<strong>诚 → 形 → 著 → 明 → 动 → 变 → 化</strong>。</p><h3 id="理-为什么值得读" tabindex="-1">理：为什么值得读 <a class="header-anchor" href="#理-为什么值得读" aria-label="Permalink to &quot;理：为什么值得读&quot;">​</a></h3><ul><li><strong>它给了普通人一条切实的路</strong>：不必等「至诚」，<strong>从一偏之善端开始</strong>。这一点极重要：全篇前面反复说中庸之难（第 9 章「不可能」、第 11 章「唯圣者能之」），到这里终于给出可行的下手处。</li><li><strong>「曲」不是缺点，是入口</strong>：朱注说人是「气则有异」，所以不能像圣人一样「举其性之全体而尽之」。既然不能求全，就从<strong>自己最真实、最擅长的那一点</strong>开始。</li><li><strong>那一串连锁讲的是「诚会自己扩布」</strong>：形、著、明、动、变、化——每一步都不是刻意为之，而是「积中发外」的自然结果。</li><li><strong>「唯天下至诚为能化」</strong>：化是至境（「不知其所以然」）。但注意：<strong>致曲者积而至化，其妙亦不异于圣人</strong>（朱注语）。</li></ul><h3 id="用-今日可用之处" tabindex="-1">用：今日可用之处 <a class="header-anchor" href="#用-今日可用之处" aria-label="Permalink to &quot;用：今日可用之处&quot;">​</a></h3><ol><li><strong>找自己的「曲」</strong>：我最真实、最容易自然流露的那一处善端是什么？就从那里开始。</li><li><strong>不求全</strong>：想做「完人」往往什么都做不成；<strong>致其一偏，做到底</strong>。</li><li><strong>信「扩布」</strong>：真实的东西会自己往外走（形→著→明→动→变→化），不必急着推广。</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>上一章说的是圣人的路：至诚尽性。这一章说的是<strong>我们的路</strong>：<strong>致曲。</strong></p><p>「曲」是一偏——你不必是全才，也不必一开始就完满。<strong>从你身上那一处真实的善端开始，把它推到底。</strong></p><p>然后会发生一连串的事：<strong>诚了就显露，显露了就显著，显著了就光明，光明了就感动人，感动了就使人转变，转变了就化育。</strong> 这条链不是你去推的，是它自己往外走的。</p><p>所以这一章其实很温柔：它承认大多数人不在「至诚」那一档，然后给出了这一档的人该怎么走。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p>待补——这一节留给自己的读后想法。</p></blockquote><p>可以按这几条慢慢写：</p><ul><li>我的「曲」（最真实、最容易自然流露的那一处善端）是什么？</li><li>「致曲」不求全——我是不是因为想「全部做好」，结果什么都没做？</li><li>诚 → 形 → 著 → 明 → 动 → 变 → 化——我见过哪一次「真实自己往外扩布」？</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸总览</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a> · <a href="/Dao/lizhimingde/sishu-wujing/lunyu/">论语</a> · <a href="/Dao/lizhimingde/sishu-wujing/mengzi/">孟子</a></li><li>上章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-22">中庸·第22章</a>　下章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-24">中庸·第24章</a></li><li>参考：《礼记》第三十一篇；朱熹《四书章句集注·中庸章句》</li></ul>',24))])}}});export{b as __pageData,x as default};
